{
 "episodeSummary": "55yo male, Non-Sustained Ventricular Tachycardia (NSVT), warning severity, hemodynamically stable",
 "rhythm": "Non-Sustained Ventricular Tachycardia (NSVT) with multifocal PVCs",
 "keyECGEvidence": [
  "morphology: Sinus beats with multifocal wide PVCs, couplets, one non-sustained VT run of 4 beats",
  "ectopyPer10s: 6",
  "regularity: occasionally irregular"
 ],
 "primaryEtiology": "Electrolyte imbalance (Hypokalemia and Hypomagnesemia)",
 "mechanism": "Low intracellular potassium and magnesium levels increase myocardial irritability and lower the threshold for ventricular automaticity and re-entry, leading to multifocal PVCs and NSVT.",
 "contributingFactors": [
  "Hydrochlorothiazide use (K/Mg wasting)",
  "Post-operative state"
 ],
 "rejectedAlternatives": [
   {
    "alternative": "Acute Myocardial Infarction",
    "why": "Troponin T 0.02 ng/mL is only mildly elevated and consistent with post-op status; no significant ST deviation noted."
   },
   {
    "alternative": "Digoxin Toxicity",
    "why": "No digoxin in medication list; morphology shows multifocal PVCs rather than classic digoxin-induced bigeminy."
   }
 ],
 "recommendedActions": [
  "Administer intravenous potassium chloride (KCl) to correct K 3.1 mmol/L LOW",
  "Administer intravenous magnesium sulfate to correct Mg 1.5 mg/dL LOW",
  "Continue continuous cardiac monitoring to monitor PVC burden and NSVT",
  "Withhold/Review Hydrochlorothiazide use in light of electrolyte depletion",
  "Monitor repeat serum electrolytes (K and Mg) in 4-6 hours"
 ],
 "uncertainty": []
}
